int main(){int t;scanf("%d",&t);while(t--){int n,k;ll p,q;scanf("%d %d %lld %lld",&n,&k,&p,&q);
 vector<ll>P1(n+1,0),P3(n+1,0);
 for(int i=1;i<=n;i++){ll a;scanf("%lld",&a);P1[i]=P1[i-1]+a%p;P3[i]=P3[i-1]+(a%q)%p;}
 vector<ll>gB(n+1,INF),gS(n+1,INF),rO(n+1,INF),rN(n+1,INF);gS[0]=0;rO[0]=0;
 ll pmR=INF,pmGS=INF,pmGB=INF;deque<int>dR,dG; // windows: rO[j]-P1[j], gS[j]-P3[j]
 auto vR=[&](int j){return rO[j]-P1[j];};auto vG=[&](int j){return gS[j]-P3[j];};
 for(int i=1;i<=n;i++){int j=i-1;
  if(rO[j]<INF){while(!dR.empty()&&vR(dR.back())>=vR(j))dR.pop_back();dR.push_back(j);}
  if(gS[j]<INF){while(!dG.empty()&&vG(dG.back())>=vG(j))dG.pop_back();dG.push_back(j);}
  if(gB[j]<INF)pmGB=min(pmGB,gB[j]-P3[j]);
  if(i-k>=0){int z=i-k;ll r=min(rO[z],rN[z]);if(r<INF)pmR=min(pmR,r-P1[z]);if(gS[z]<INF)pmGS=min(pmGS,gS[z]-P3[z]);}
  while(!dR.empty()&&dR.front()<=i-k)dR.pop_front();while(!dG.empty()&&dG.front()<=i-k)dG.pop_front();
  if(pmR<INF)gB[i]=P1[i]+pmR;
  if(!dR.empty())gS[i]=P1[i]+vR(dR.front());
  ll b=min(pmGB,pmGS);if(b<INF)rO[i]=P3[i]+b;
  if(!dG.empty())rN[i]=P3[i]+vG(dG.front());}
 printf("%lld\n",min({gB[n],gS[n],rO[n]}));}}

